CREATE TABLE currency_registry(code char(3) PRIMARY KEY, minor_units smallint NOT NULL CHECK (minor_units BETWEEN 0 AND 4), enabled boolean NOT NULL);
INSERT INTO currency_registry VALUES ('INR',2,true),('USD',2,true);
CREATE TABLE store_currency(id smallint PRIMARY KEY CHECK(id=1), code char(3) NOT NULL REFERENCES currency_registry(code), revision integer NOT NULL DEFAULT 1);
INSERT INTO store_currency VALUES(1,'INR',1);
CREATE TABLE sku_price(sku_id uuid NOT NULL, currency char(3) NOT NULL REFERENCES currency_registry(code), amount_minor bigint NOT NULL CHECK(amount_minor > 0), revision integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(sku_id,currency));
CREATE TABLE price_audit(id bigserial PRIMARY KEY, sku_id uuid NOT NULL, currency char(3) NOT NULL, amount_minor bigint NOT NULL, actor varchar(160) NOT NULL, revision integer NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE coupon(id uuid PRIMARY KEY, code varchar(40) NOT NULL UNIQUE, active boolean NOT NULL DEFAULT false, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, currency char(3) NOT NULL REFERENCES currency_registry(code), kind varchar(12) NOT NULL CHECK(kind IN ('FIXED','PERCENT')), value bigint NOT NULL CHECK(value > 0), minimum_subtotal_minor bigint NOT NULL DEFAULT 0 CHECK(minimum_subtotal_minor >= 0), maximum_discount_minor bigint, global_limit bigint, per_customer_limit integer, rules jsonb NOT NULL DEFAULT '{}'::jsonb, revision integer NOT NULL DEFAULT 1, CHECK(ends_at > starts_at), CHECK(kind <> 'PERCENT' OR value <= 10000), CHECK(maximum_discount_minor IS NULL OR maximum_discount_minor > 0));
